package org.apache.commons.math.stat.descriptive;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.StorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.SecondMoment;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.rank.Max;
import org.apache.commons.math.stat.descriptive.rank.Min;
import org.apache.commons.math.stat.descriptive.summary.Sum;
import org.apache.commons.math.stat.descriptive.summary.SumOfLogs;
import org.apache.commons.math.stat.descriptive.summary.SumOfSquares;
import org.apache.commons.math.stat.descriptive.univariate.GeometricMean;
import org.apache.commons.math.stat.descriptive.univariate.Mean;
import org.apache.commons.math.stat.descriptive.univariate.Variance;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class SummaryStatistics_addValue_TriageGen2Test {

    private SummaryStatistics stats;

    @Before
    public void setUp() {
        stats = new SummaryStatistics();
    }

    @Test
    public void testAddValue_StandardBehavior() {
        // Test with standard implementations (where the 'if' conditions are false)
        // The default implementations for Mean, Variance, and GeometricMean are usually 
        // subclasses of the interfaces, so the 'if (!(impl instanceof Type))' should be false.

        double val = 10.0;
        stats.addValue(val);

        assertEquals(1, stats.getN());
        assertEquals(val, stats.getSum(), 1e-10);
        assertEquals(val * val, stats.getSumsq(), 1e-10);
        assertEquals(val, stats.getMean(), 1e-10);
        assertEquals(val, stats.getMax(), 1e-10);
        assertEquals(val, stats.getMin(), 1e-10);
        assertEquals(Math.log(val), stats.getSumOfLogs(), 1e-10);
        assertEquals(val * val, stats.getSecondMoment(), 1e-10);
    }

    @Test
    public void testAddValue_MultipleValues() {
        stats.addValue(2.0);
        stats.addValue(4.0);

        assertEquals(2, stats.getN());
        assertEquals(6.0, stats.getSum(), 1e-10);
        assertEquals(20.0, stats.getSumsq(), 1e-10); // 4 + 16
        assertEquals(3.0, stats.getMean(), 1e-10);
        assertEquals(4.0, stats.getMax(), 1e-10);
        assertEquals(2.0, stats.getMin(), 1e-10);
    }

    @Test
    public void testAddValue_WithCustomMeanImplementation() {
        // This triggers the branch: if (!(meanImpl instanceof Mean))
        // We mock a StorelessUnivariateStatistic that is NOT an instance of Mean
        StorelessUnivariateStatistic mockMean = mock(StorelessUnivariateStatistic.class);
        stats.setMeanImpl(mockMean);

        double val = 5.0;
        stats.addValue(val);

        // Verify that increment was called because it's NOT an instance of Mean
        verify(mockMean, times(1)).increment(val);
        assertEquals(1, stats.getN());
    }

    @Test
    public void testAddValue_WithCustomVarianceImplementation() {
        // This triggers the branch: if (!(varianceImpl instanceof Variance))
        StorelessUnivariateStatistic mockVariance = mock(StorelessUnivariateStatistic.class);
        stats.setVarianceImpl(mockVariance);

        double val = 5.0;
        stats.addValue(val);

        verify(mockVariance, times(1)).increment(val);
    }

    @Test
    public void testAddValue_WithCustomGeoMeanImplementation() {
        // This triggers the branch: if (!(geoMeanImpl instanceof GeometricMean))
        StorelessUnivariateStatistic mockGeoMean = mock(StorelessUnivariateStatistic.class);
        stats.setGeoMeanImpl(mockGeoMean);

        double val = 5.0;
        stats.addValue(val);

        verify(mockGeoMean, times(1)).increment(val);
    }

    @Test
    public void testAddValue_WithCustomImplsThatAreInstancesOfTypes() {
        // This tests the branches where the 'if' condition is FALSE
        // i.e., the implementation IS an instance of the specified class

        Mean mockMean = mock(Mean.class);
        Variance mockVariance = mock(Variance.class);
        GeometricMean mockGeoMean = mock(GeometricMean.class);

        stats.setMeanImpl(mockMean);
        stats.setVarianceImpl(mockVariance);
        stats.setGeoMeanImpl(mockGeoMean);

        double val = 5.0;
        stats.addValue(val);

        // Because they ARE instances of the types, increment should NOT be called on them 
        // via the conditional blocks (they are handled by the internal logic or assumed handled)
        verify(mockMean, never()).increment(anyDouble());
        verify(mockVariance, never()).increment(anyDouble());
        verify(mockGeoMean, never()).increment(anyDouble());
    }

    @Test
    public void testAddValue_ZeroAndNegative() {
        stats.addValue(0.0);
        assertEquals(1, stats.getN());
        assertEquals(0.0, stats.getSum(), 1e-10);

        stats.addValue(-5.0);
        assertEquals(2, stats.getN());
        assertEquals(-5.0, stats.getSum(), 1e-10);
        assertEquals(-5.0, stats.getMax(), 1e-10);
        assertEquals(-5.0, stats.getMin(), 1e-10);
    }
}
